<script setup lang="ts">
const form=reactive({name:'',email:'',password:''});const busy=ref(false);const error=ref('')
async function submit(){busy.value=true;error.value='';try{await $fetch('/api/auth/register',{method:'POST',body:form});await navigateTo('/')}catch(e:any){error.value=e.data?.statusMessage||e.message||'Could not create your account. Check the database connection and try again.'}finally{busy.value=false}}
</script>
<template><div class="mx-auto max-w-md rounded-2xl bg-white p-7 shadow-sm"><p class="text-sm font-semibold text-emerald-700">START YOUR ROUTINE</p><h1 class="mt-2 text-2xl font-semibold">Create your account</h1><p class="mt-2 text-sm text-stone-500">Your nutrition and habits stay connected to your account.</p><p v-if="error" role="alert" class="mt-5 rounded-xl bg-rose-50 p-4 text-sm text-rose-800">{{error}}</p><form class="mt-6 space-y-4" @submit.prevent="submit"><label class="block text-sm">Name<input v-model="form.name" autocomplete="name" maxlength="80" required class="mt-1 w-full rounded-lg border p-3"></label><label class="block text-sm">Email<input v-model="form.email" type="email" autocomplete="email" required class="mt-1 w-full rounded-lg border p-3"></label><label class="block text-sm">Password<input v-model="form.password" type="password" autocomplete="new-password" minlength="8" required class="mt-1 w-full rounded-lg border p-3"><span class="mt-1 block text-xs text-stone-400">Use at least 8 characters.</span></label><button class="w-full rounded-xl bg-emerald-800 p-3 font-semibold text-white disabled:opacity-60" :disabled="busy">{{busy?'Creating account…':'Create account'}}</button></form><p class="mt-5 text-center text-sm text-stone-500">Already have an account? <NuxtLink to="/login" class="font-semibold text-emerald-800">Log in</NuxtLink></p></div></template>
